mapper.select:
        SELECT
            TEMP.*, 
            bbd.BOOKSET_DATE AS booksetDate
        FROM (
	        SELECT 
	            bc.BOOKSET_ID AS booksetId,    
				bc.BOK_DETAIL_ID as bokDetailId,    
				bdi.BUSI_ID as busiId,  
				bdi.BUSI_DETAIL_TYPE as busiDetailType, 
				bc.TABLE_ID AS tableId, 
				bc.SUBJECT_NO AS subjectNo,    
				bdi.INV_AIM as invAim,  
				bc.O_CCY AS oCcy,   
				bc.B_CCY AS bCcy,   
				bc.BAL_FLAG_HAPPEN_DATE as balFlagHappenDate,   
				bc.O_AMT_HAPPEN_DATE AS balance,    
				bc.B_AMT_HAPPEN_DATE AS bAmt, 
				bc.NUM_AMT_HAPPEN_DATE AS num,  
				bc.SHARE_AMT_CLEAN AS shareAmtClean,  
				bc.rn,
				bc.HAPPEN_DATE AS happenDate,   
				bc.BASE_SUBJECT_NATURE as baseSubjectNature,    

				bc.DETAIL_SUBJECT_NO AS detailSubjectNo,     
                bs.BAL_FLAG
				,bc.MDATE mdate
		    FROM (
                SELECT
                    tmp.*,
                    @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
                IF(
                    (
                        @BOOKSET_ID = tmp.BOOKSET_ID
                        and @BOK_DETAIL_ID = tmp.BOK_DETAIL_ID
                        and @BASE_SUBJECT_NATURE = tmp.BASE_SUBJECT_NATURE
                        and @O_CCY = tmp.O_CCY
                    ), @rank := @rank + 1, @rank := 1
                ) AS rn, /* 分组虚拟列行标 */
                @TRADE_ID := tmp.TRADE_ID /* 分组条件1 */
                , @BOK_DETAIL_ID := tmp.BOK_DETAIL_ID /* 分组条件1 */
                , @BASE_SUBJECT_NATURE := tmp.BASE_SUBJECT_NATURE /* 分组条件1 */
                , @O_CCY := tmp.O_CCY /* 分组条件1 */
                FROM (
                    /* 数据源 */
                    SELECT * FROM BOK_BOOKDETAIL_CURRENT ORDER BY BOOK_ORDER DESC
                ) tmp,
                /* 定义临时变量池 */
                (
                    SELECT @rownum := 0,
                    @BOOKSET_ID := null,
                    @BOK_DETAIL_ID := null,
                    @BASE_SUBJECT_NATURE := null,
                    @O_CCY := null,
                    @rank := 0
                ) a
            ) bc
		    LEFT JOIN BOK_DETAIL_ID bdi ON bdi.BOOKSET_ID = bc.BOOKSET_ID AND bdi.BOK_DETAIL_ID = bc.BOK_DETAIL_ID
		    LEFT JOIN SYS_BATCH_TASK bt on bt.task_id = bc.task_id 
		    LEFT JOIN BOK_BOOKSET bb ON bc.BOOKSET_ID = bb.BOOKSET_ID
		    LEFT JOIN BOK_SUBJECT bs ON bs.BOOKSET_ID = bb.BOOKSET_ID_TMPL AND bs.SUBJECT_NO = bc.SUBJECT_NO
		    WHERE 1=1

	            AND bc.BOOKSET_ID = #{booksetId} 



	            AND bdi.BUSI_ID = #{busiId}


	            AND bc.HAPPEN_DATE <= #{happenDate}


				AND (
					bc.HAPPEN_DATE < #{happenDate} 
					OR
					( bc.HAPPEN_DATE = #{happenDate} AND ifnull(bt.task_pri,bc.TASK_PRI) < #{taskPri} )
				)


	            AND bc.BOOK_DATE <= #{bookDate}
	            AND (bc.OFFSET_DATE < #{bookDate} OR bc.OFFSET_DATE IS NULL)



	            AND bdi.INV_AIM IN

	                #{invAim}



	            AND bc.BASE_SUBJECT_NATURE IN

	                #{baseSubjectNature}



	            AND bc.TABLE_ID = #{tableId}


	            AND bs.SUBJECT_TYPE IN

	                #{subjectType}



				    	AND bc.BOK_DETAIL_ID in

				                #{item}



	            AND bc.BOK_DETAIL_ID = #{bokDetailId}


	            AND bc.BOOK_ORDER <= #{bookOrder}



	            AND ( bc.ONWAY_DATE <= #{onwayDate} OR bc.ONWAY_DATE IS NULL )






		            AND bc.BRANCH = #{branch}


        ) TEMP
        INNER JOIN BOK_BOOKSET_DATE bbd
            ON bbd.BOOKSET_ID = TEMP.booksetId
        WHERE TEMP.rn=1

	    SELECT
	        temp.*, 
	        bbd.BOOKSET_DATE AS booksetDate
		FROM (
		    SELECT 
            ba.BOOKSET_ID AS booksetId,    
            ba.BOK_DETAIL_ID as bokDetailId,   
			ba.TABLE_ID AS tableId,    
			ba.BASE_SUBJECT_NATURE as baseSubjectNature,    
			ba.O_CCY AS oCcy,  
			ba.O_AMT_HAPPEN_DATE as oAmtHappenDate,    
			ba.B_AMT_BOOK_DATE as bAmtHappenDate,    
			ba.NUM_AMT_HAPPEN_DATE as numAmtHappenDate,    
			ba.BAL_FLAG_HAPPEN_DATE as balFlagHappenDate,    
			ba.O_AMT_BOOK_DATE as oAmtBookDate,    
			ba.B_AMT_BOOK_DATE as bAmtBookDate,    
			ba.NUM_AMT_BOOK_DATE as numAmtBookDate,    
			ba.BAL_FLAG_BOOK_DATE as balFlagBookDate,
            ba.rn,
			ba.BOOK_DATE AS bookDate        
		 FROM (

            SELECT
                tmp.*,
                @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
                IF(
                    (
                        @BOOKSET_ID = tmp.BOOKSET_ID
                        and @BOK_DETAIL_ID = tmp.BOK_DETAIL_ID
                        and @BASE_SUBJECT_NATURE = tmp.BASE_SUBJECT_NATURE
                        and @BRANCH = tmp.BRANCH
                        and @O_CCY = tmp.O_CCY
                    ),
                    @rank := @rank + 1,
                    @rank := 1
                ) AS rn, /* 分组虚拟列行标 */
                @TRADE_ID := tmp.TRADE_ID /* 分组条件1 */
                , @BOK_DETAIL_ID := tmp.BOK_DETAIL_ID /* 分组条件1 */
                , @BASE_SUBJECT_NATURE := tmp.BASE_SUBJECT_NATURE /* 分组条件1 */
                , @BRANCH := tmp.BRANCH /* 分组条件1 */
                , @O_CCY := tmp.O_CCY /* 分组条件1 */
            FROM (
                /* 数据源 */
                SELECT * FROM BOK_BOOKDETAIL_ALL ORDER BY BOOK_ORDER DESC
            ) tmp,
            /* 定义临时变量池 */
            (
                SELECT @rownum := 0,
                @BOOKSET_ID := null,
                @BOK_DETAIL_ID := null,
                @BASE_SUBJECT_NATURE := null,
                @BRANCH := null,
                @O_CCY := null,
                @rank := 0
            ) a
        ) ba
		 WHERE 1=1

		         AND ba.BOOKSET_ID = #{booksetId} 


		         AND ba.HAPPEN_DATE < #{happenDate}


		      AND ba.BOOK_DATE < #{bookDate}


		         AND ba.BASE_SUBJECT_NATURE IN

		             #{baseSubjectNature}



		         AND ba.BOK_DETAIL_ID = #{bokDetailId}

		 ) TEMP
		INNER JOIN BOK_BOOKSET_DATE bbd
		    ON bbd.BOOKSET_ID = TEMP.BOOKSETID
		WHERE TEMP.rn=1

    	SELECT
           *
        FROM(
            SELECT
                   a.BOOKSET_ID          AS booksetId, 
			       a.HAPPEN_DATE         AS happenDate, 
			       a.BOOK_DATE           AS bookDate, 
			       a.BOOKSET_DATE        AS booksetDate, 
			       a.PROFIT_TYPE         AS profitType, 
			       a.CAPITAL             AS capital, 
			       a.NET_ASSET_VALUE_BEF AS netAssetValueBef, 
			       a.NET_ASSET_VALUE     AS netAssetValue, 
			       a.NET_UNIT_VALUE_BEF  AS netUnitValueBef, 
			       a.NET_UNIT_VALUE      AS netUnitValue, 
			       a.P_YIELD_BEF         AS pYieldBef, 
			       a.P_YIELD             AS pYield, 
			       a.TDY_YIELD_BEF       AS tdyYieldBef, 
			       a.TDY_YIELD           AS tdyYield, 
			       a.YIELD_TERM_BEF      AS yieldTermBef, 
			       a.YIELD_TERM          AS yieldTerm, 
			       a.YIELD_7_BEF         AS yield7Bef, 
			       a.YIELD_7             AS yield7, 
			       a.TOT_BOUNS_AMT       AS totBounsAmt, 
			       a.TDY_BOUNS_AMT       AS tdyBounsAmt, 
			       a.TOT_BOUNS_NET       AS totBounsNet, 
			       a.TDY_BOUNS_NET       AS tdyBounsNet, 
			       a.PROFIT_AMT          AS profitAmt, 
                   a.TOT_PROFIT_AMT      AS totProfitAmt, 
                   a.INT_RATE            AS intRate,
			       a.rn
            FROM (

                SELECT
                    tmp.*,
                    @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
                    IF(
                        (
                            @BOOKSET_ID = tmp.BOOKSET_ID
                            and @HAPPEN_DATE = tmp.HAPPEN_DATE
                        ),
                        @rank := @rank + 1,
                        @rank := 1
                    ) AS rn, /* 分组虚拟列行标 */
                    @BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
                    , @HAPPEN_DATE := tmp.HAPPEN_DATE /* 分组条件1 */
                FROM (
                    /* 数据源 */
                    SELECT * FROM BOK_STAT_BOK_POSITION ORDER BY BOOKSET_DATE DESC
                ) tmp,
                /* 定义临时变量池 */
                (
                    SELECT @rownum := 0,
                    @BOOKSET_ID := null,
                    @HAPPEN_DATE := null,
                    @rank := 0
                ) a
            ) a
            WHERE 
            1 = 1

            AND a.HAPPEN_DATE <= #{sdateEnd}


            AND a.HAPPEN_DATE >= #{sdateStart}


                AND a.HAPPEN_DATE IN

                    #{item}



            	AND a.BOOKSET_ID = #{booksetId}


            	AND a.BOOK_DATE <= #{bookDate}


            	AND a.FINPROD_ID = #{finprodId}


            	AND a.layering_Id = #{layeringId}


            	AND a.is_sub_prd = #{isSubPrd}



            	AND EXISTS (
		             SELECT * FROM BOK_ACCT_LAYERING_INFO b 
		             WHERE b.bookset_id = a.bookset_id 
		             AND b.layering_id = a.layering_id
		             AND b.bok_detail_id = #{bokDetailId}
	            )


        )
        WHERE  rn = 1

SELECT E.FINPROD_ID, E.FINPROD_TYPE, E.VDATE, E.TRADE_MARKET, E.CALENDAR_ID, E.ACTMDATE, F.CASH_ID, F.CASH_TYPE_1, F.CASH_TYPE_2, G.BOOKSET_ID, G.BOOKSET_DATE, G.BOOK_DATE, G.STANDARD_CCY, VBD.BOK_DETAIL_ID FROM ( SELECT B.BOOKSET_ID, B.ACCT_SUBJECT_ID, B.STANDARD_CCY, H.BOOKSET_DATE, H.BOOK_DATE FROM BOK_BOOKSET B INNER JOIN BOK_BATCH_TASK_TODO H ON B.BOOKSET_ID=H.BOOKSET_ID AND B.ACCT_SUBJECT_TYPE = #{accSubjectType} where 1=1 AND H.SEQ_NO = #{seqNo} AND H.BOOKSET_DATE = #{BOOKSET_DATE} AND H.BOOK_DATE = #{BOOK_DATE} AND H.HAPPEN_DATE = #{HAPPEN_DATE} AND H.TASK_ID = #{taskId} ) G left JOIN FIN_PRODUCT E ON E.FINPROD_ID = G.ACCT_SUBJECT_ID INNER JOIN FIN_CASH_INFO F ON g.ACCT_SUBJECT_ID = F.FINPROD_ID
AND F.CASH_TYPE_2 IN
#{cashType}
INNER JOIN BOK_DETAIL_ID VBD ON F.FINPROD_ID = VBD.BUSI_ID
and VBD.BOOKSET_ID=g.BOOKSET_ID
WHERE E.VDATE<=#{HAPPEN_DATE} AND E.ACTMDATE>=#{HAPPEN_DATE}
AND E.PROFIT_TYPE = #{profitType}

select
	ifnull(MAX(
		CAST(


			SUBSTRING(BUS_VOUCHNUM,9)
	)),'000000')
from
	BOK_VOUCH_MAIN
where
	VOUCH_YEAR = #{vouchYear}
	AND VOUCH_MONTH = #{vouchMonth}
	AND BOOKSET_ID = #{booksetId}

    SELECT
    	TEMP.*
    FROM(
    	SELECT 
    		b.SUBJECT_NO,
    		b.BASE_SUBJECT_NATURE,
    		b.rowno
    	FROM BOK_SCENESUBJECT a,(
            SELECT SCENE_NODE_ID
            FROM BOK_SCENESUBJECT
            WHERE SUBJECT_NO = #{subjectNo}
            AND BOOKSET_ID = #{booksetId}
        ) TMP,(

            SELECT
                tmp.*,
                @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
                IF(
                    (
                    @BASE_SUBJECT_NATURE = tmp.BASE_SUBJECT_NATURE
                    ),
                    @rank := @rank + 1,
                    @rank := 1
                ) AS rowno, /* 分组虚拟列行标 */
                @BASE_SUBJECT_NATURE := tmp.BASE_SUBJECT_NATURE /* 分组条件1 */
            FROM (
                /* 数据源 */
                SELECT * FROM BOK_SUBJECT ORDER BY SUBJECT_NO asc
            ) tmp,
            /* 定义临时变量池 */
            (
                SELECT @rownum := 0,
                @BASE_SUBJECT_NATURE := null,
                @rank := 0
            ) a
        ) b
    	WHERE a.SCENE_NODE_ID = TMP.SCENE_NODE_ID
    	AND a.BOOKSET_ID = #{booksetId}
    	AND a.BOOKSET_ID = b.BOOKSET_ID
    	AND a.SUBJECT_NO = b.SUBJECT_NO
    	AND b.BASE_SUBJECT_NATURE IN (

		    	#{item}

    	)
    ) TEMP
    WHERE TEMP.rowno = 1

SELECT										
	TEMP.*							
FROM			
(
	SELECT							
		cur.*,
    book.BOOKSET_DATE	BOOKSET_DATE_NEW
	FROM
		(
         SELECT tmp.*,
                @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
                IF(
                    (
                        @BOOKSET_ID = tmp.BOOKSET_ID
                        and @TRADE_ID = tmp.TRADE_ID
                        and @BASE_SUBJECT_NATURE = tmp.BASE_SUBJECT_NATURE
                        and @O_CCY = tmp.O_CCY
                    ), @rank := @rank + 1, @rank := 1) AS rn, /* 分组虚拟列行标 */
                @BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
                , @TRADE_ID := tmp.TRADE_ID /* 分组条件1 */
                , @BASE_SUBJECT_NATURE := tmp.BASE_SUBJECT_NATURE /* 分组条件1 */
                , @O_CCY := tmp.O_CCY /* 分组条件1 */
         FROM (
                  /* 数据源 */
                  SELECT * FROM BOK_BOOKDETAIL_CURRENT ORDER BY BOOK_ORDER desc
              ) tmp,
              /* 定义临时变量池 */
              (SELECT @rownum := 0,
                      @BOOKSET_ID := null,
                      @TRADE_ID := null,
                      @BASE_SUBJECT_NATURE := null,
                      @O_CCY := null,
                      @rank := 0) a

     ) cur
	INNER JOIN BOK_BOOKSET_DATE book ON book.BOOKSET_ID = cur.BOOKSET_ID
	WHERE							
		cur.BOOKSET_ID = #{booksetId}	
		AND		cur.BOOK_DATE <= #{bookDate}		
		AND		cur.TRADE_ID = #{tradeId}			
	) TEMP									
  WHERE									
		TEMP.rn = 1

		 SELECT
			 crt.*,
			 book.BOOKSET_DATE booksetDateNew 
		 FROM BOK_BOOKDETAIL_CURRENT crt
		 INNER JOIN (
            SELECT
            TEMP.happenDate,
            TEMP.booksetDate,
            TEMP.bookDate,
            TEMP.bookId,
            TEMP.booksetId
            FROM (
                SELECT
                cur.HAPPEN_DATE as happenDate,
                cur.BOOKSET_DATE as booksetDate,
                cur.BOOK_DATE as bookDate,
                cur.BOOK_ID as bookId,
                cur.BOOKSET_ID as booksetId,
                cur.OFFSET_FLAG as offsetFlag,
                cur.rn
                FROM (

                    SELECT
                        tmp.*,
                        @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
                        IF(
                            (
                            @BOOKSET_ID = tmp.BOOKSET_ID
                            and @BOOK_ID = tmp.BOOK_ID
                            ),
                            @rank := @rank + 1,
                            @rank := 1
                        ) AS rn, /* 分组虚拟列行标 */
                        @BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
                        , @BOOK_ID := tmp.BOOK_ID /* 分组条件1 */
                    FROM (
                        /* 数据源 */
                        SELECT * FROM BOK_BOOKDETAIL_CURRENT ORDER BY BOOK_ORDER desc
                    ) tmp,
                    /* 定义临时变量池 */
                    (
                        SELECT @rownum := 0,
                        @BOOKSET_ID := null,
                        @BOOK_ID := null,
                        @rank := 0
                    ) a
                ) cur
                WHERE 1=1
                AND cur.BOOKSET_ID = #{booksetId}
                AND cur.BOOK_DATE <= #{bookDate}
                 AND cur.TABLE_ID = #{tableId}  
                 AND cur.TRADE_ID = #{tradeId}  
                 AND cur.HAPPEN_DATE = #{happenDate}	 
                 AND cur.HAPPEN_DATE >= #{beginHappenCycDate} 
                 AND cur.HAPPEN_DATE <= #{endHappenCycDate} 
            ) TEMP
            WHERE TEMP.rn = 1
            AND TEMP.offsetFlag = #{offsetFlag}
        ) vr on crt.happen_date = vr.happenDate
		                       and crt.BOOKSET_DATE = vr.booksetDate
		                       and crt.BOOK_DATE = vr.bookDate
		                       and crt.BOOK_ID =  vr.bookId
		                       and crt.bookset_id = vr.booksetId
		 INNER JOIN BOK_BOOKSET_DATE book ON book.BOOKSET_ID = crt.BOOKSET_ID                      
		 WHERE 1 =1 


			AND crt.BASE_SUBJECT_NATURE IN

				#{baseSubjectNature}



			AND crt.BOK_DETAIL_ID = #{bokDetailId}	


			AND ( crt.HAPPEN_DATE <= #{onwayDate} AND crt.ONWAY_DATE > #{onwayDate})

		 ORDER BY crt.HAPPEN_DATE ASC

		SELECT 
			TMP.*
		FROM (
		      SELECT 
		        A.*
		      FROM (
		        SELECT
                    tmp.*,
                    @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
                    IF(
                        (
                        @BOOKSET_ID = tmp.BOOKSET_ID
                        and @BOK_DETAIL_ID = tmp.BOK_DETAIL_ID
                        and @HAPPEN_DATE = tmp.HAPPEN_DATE
                        ), @rank := @rank + 1, @rank := 1
                    ) AS rn, /* 分组虚拟列行标 */
                    @BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
                    , @BOK_DETAIL_ID := tmp.BOK_DETAIL_ID /* 分组条件1 */
                    , @HAPPEN_DATE := tmp.HAPPEN_DATE /* 分组条件1 */
                FROM (
                    /* 数据源 */
                    SELECT * FROM BOK_STAT_DET_POSIITON ORDER BY BOOK_SUMMARY_ORDER desc
                ) tmp,
                /* 定义临时变量池 */
                (SELECT @rownum := 0,
                @BOOKSET_ID := null,
                @BOK_DETAIL_ID := null,
                @HAPPEN_DATE := null,
                @rank := 0) a
              ) A
		      WHERE 1=1
		       AND A.HAPPEN_DATE <= #{endDate} 
		       AND A.HAPPEN_DATE >= #{beginDate} 

		      	AND A.HAPPEN_DATE IN 

		      		#{datenow}


		      AND A.BOOKSET_ID = #{booksetId} 

                  AND A.BOK_DETAIL_ID = #{bokDetailId} 


                  AND A.BUSI_ID = #{busiId} 

		      AND A.BOOK_DATE <= #{bookDate} 
		) TMP WHERE TMP.rn = 1

SELECT tmp.finprod_Id finprodId, tmp.finprod_Type finprodType, tmp.VDATE, tmp.mdate actmdate, tmp.calendar_Id calendarId, tmp.branch, tmp.ACCT_MODE acctMode, C.CASH_ID cashId, C.CASH_TYPE_1 cashType1, C.CASH_TYPE_2 cashType2, tmp.BOOKSET_ID booksetId, tmp.BOOKSET_DATE booksetDate, tmp.BOOK_DATE bookDate, tmp.STANDARD_CCY standardCcy, tmp.lev, tmp.layeringId, BOK.BOK_DETAIL_ID bokDetailId from (SELECT B.BOOKSET_ID BOOKSET_ID, B.STANDARD_CCY STANDARD_CCY, B.ACCT_MODE ACCT_MODE, f.vdate, f.mdate, f.layering_id layeringId, f.busi_id finprod_Id, f.busi_detail_type finprod_Type, f.calendar_id calendar_Id, f.branch, H.BOOKSET_DATE BOOKSET_DATE, H.BOOK_DATE BOOK_DATE, f.lev lev FROM BOK_BOOKSET B INNER JOIN BOK_BATCH_TASK_TODO H ON B.BOOKSET_ID = H.BOOKSET_ID INNER JOIN BOK_ACCT_LAYERING_INFO f on b.bookset_id = f.bookset_id WHERE 1=1
AND B.acct_mode = #{profitType}
and (f.vdate <= #{cdate} or f.vdate is null) and (f.mdate >= #{cdate} or f.mdate is null) and h.seq_no = #{seqNo,jdbcType=VARCHAR} and h.bookset_date =#{BOOKSET_DATE,jdbcType=DATE} and h.book_date =#{BOOK_DATE,jdbcType=DATE} and h.happen_date =#{HAPPEN_DATE,jdbcType=DATE} and h.task_id = #{taskId,jdbcType=VARCHAR} AND H.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET} ) TMP INNER JOIN FIN_CASH_INFO C ON tmp.FINPROD_ID = C.FINPROD_ID and tmp.branch = c.branch
AND c.CASH_TYPE_2 IN
#{item}
and (c.IS_CALC = #{isCalc,jdbcType=VARCHAR} or c.IS_CALC is null) INNER JOIN BOK_DETAIL_ID BOK ON tmp.FINPROD_ID = BOK.BUSI_ID AND tmp.FINPROD_TYPE = BOK.BUSI_DETAIL_TYPE and tmp.BOOKSET_ID = BOK.BOOKSET_ID and tmp.branch = BOK.branch

SELECT 																															
	count(1)																														
FROM																															
(																														
		SELECT																													
			cur.OFFSET_FLAG,																									
			cur.rn
		FROM (
            SELECT tmp.*,
            @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
            IF(
            (
            @BOOKSET_ID = tmp.BOOKSET_ID
            and @BOOK_ID = tmp.BOOK_ID
            ), @rank := @rank + 1, @rank := 1) AS rn, /* 分组虚拟列行标 */
            @BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
            , @BOOK_ID := tmp.BOOK_ID /* 分组条件1 */
            FROM (
            /* 数据源 */
            SELECT * FROM BOK_BOOKDETAIL_CURRENT ORDER BY BOOK_ORDER desc
            ) tmp,
            /* 定义临时变量池 */
            (SELECT @rownum := 0,
            @BOOKSET_ID := null,
            @BOOK_ID := null,
            @rank := 0) a
        )	cur
		WHERE																													
			 cur.BOOKSET_ID = #{booksetId}																									
			AND cur.BOOK_DATE <= #{bookDate} 	
			 AND cur.TABLE_ID = #{tableId}	

			AND ((cur.HAPPEN_DATE = #{happenDate} AND cur.ONWAY_DATE  is NULL)
				 OR cur.ONWAY_DATE = #{happenDate})																								

	            AND cur.BASE_SUBJECT_NATURE IN

	                #{baseSubjectNature}



				AND cur.BOK_DETAIL_ID = #{bokDetailId}

	) a
	WHERE																														
		rn=1																													
	AND	OFFSET_FLAG = #{offsetFlag}

		 SELECT
			 crt.*
		 FROM BOK_BOOKDETAIL_CURRENT crt
		 INNER JOIN (
        SELECT
        TEMP.happenDate,
        TEMP.booksetDate,
        TEMP.bookDate,
        TEMP.bookId,
        TEMP.booksetId
        FROM (
        SELECT
        cur.HAPPEN_DATE as happenDate,
        cur.BOOKSET_DATE as booksetDate,
        cur.BOOK_DATE as bookDate,
        cur.BOOK_ID as bookId,
        cur.BOOKSET_ID as booksetId,
        cur.OFFSET_FLAG as offsetFlag,
        cur.rn
        FROM (
        SELECT tmp.*,
        @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
        IF(
        (
        @BOOKSET_ID = tmp.BOOKSET_ID
        and @BOOK_ID = tmp.BOOK_ID
        ), @rank := @rank + 1, @rank := 1) AS rn, /* 分组虚拟列行标 */
        @BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
        , @BOOK_ID := tmp.BOOK_ID /* 分组条件1 */
        FROM (
        /* 数据源 */
        SELECT * FROM BOK_BOOKDETAIL_CURRENT ORDER BY BOOK_ORDER desc
        ) tmp,
        /* 定义临时变量池 */
        (SELECT @rownum := 0,
        @BOOKSET_ID := null,
        @BOOK_ID := null,
        @rank := 0) a
        ) cur
        WHERE 1=1
        AND cur.BOOKSET_ID = #{booksetId}
        AND cur.BOOK_DATE <= #{bookDate}


            AND cur.TABLE_ID IN

                #{tableId}


         AND cur.TRADE_ID = #{tradeId}  
         AND cur.HAPPEN_DATE <= #{happenDate}	 
         AND cur.HAPPEN_DATE >= #{beginHappenCycDate} 
         AND cur.HAPPEN_DATE <= #{endHappenCycDate} 
        ) TEMP
        WHERE TEMP.rn = 1
        AND TEMP.offsetFlag = #{offsetFlag}
        ) vr on crt.happen_date = vr.happenDate
		                       and crt.BOOKSET_DATE = vr.booksetDate
		                       and crt.BOOK_DATE = vr.bookDate
		                       and crt.BOOK_ID =  vr.bookId                 
		 WHERE 1 =1 


			AND crt.BASE_SUBJECT_NATURE IN

				#{baseSubjectNature}



			AND crt.BOK_DETAIL_ID = #{bokDetailId}	


			AND ( crt.HAPPEN_DATE <= #{onwayDate} AND crt.ONWAY_DATE > #{onwayDate})

		 	AND crt.MDATE is not null
		 ORDER BY crt.MDATE DESC

SELECT * from BOK_ACCT_LAYERING_INFO i where 1=1
and i.bookset_Id=#{booksetId}
and (i.lev like concat_ws('',#{lev},'-%') or i.lev = #{lev})

SELECT tmp.FINPROD_ID finprodId, tmp.FINPROD_TYPE finprodType, tmp.start_date VDATE, tmp.end_date ctmdate, C.CASH_ID cashId, C.CASH_TYPE_1 cashType1, C.CASH_TYPE_2 cashType2, tmp.BOOKSET_ID booksetId, tmp.BOOKSET_DATE booksetDate, tmp.BOOK_DATE bookDate, tmp.STANDARD_CCY standardCcy, BOK.BOK_DETAIL_ID bokDetailId from (SELECT B.BOOKSET_ID BOOKSET_ID, b.acct_subject_id FINPROD_ID, b.acct_subject_type FINPROD_TYPE, B.STANDARD_CCY STANDARD_CCY, b.start_date, b.end_date, H.BOOKSET_DATE BOOKSET_DATE, H.BOOK_DATE BOOK_DATE FROM BOK_BOOKSET B INNER JOIN BOK_BATCH_TASK_TODO H ON B.BOOKSET_ID = H.BOOKSET_ID WHERE 1=1
AND B.acct_mode = #{profitType,jdbcType=VARCHAR}
and (b.start_date <= #{cdate} or b.start_date is null) and (b.end_date >= #{cdate} or b.end_date is null) and h.seq_no = #{seqNo,jdbcType=VARCHAR} and h.bookset_date =#{BOOKSET_DATE,jdbcType=DATE} and h.book_date =#{BOOK_DATE,jdbcType=DATE} and h.happen_date =#{HAPPEN_DATE,jdbcType=DATE} and h.task_id = #{taskId,jdbcType=VARCHAR} AND H.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET} ) TMP INNER JOIN FIN_CASH_INFO C ON tmp.FINPROD_ID = C.FINPROD_ID
AND c.CASH_TYPE_2 IN
#{item}
INNER JOIN BOK_DETAIL_ID BOK ON tmp.FINPROD_ID = BOK.BUSI_ID AND tmp.FINPROD_TYPE = BOK.BUSI_DETAIL_TYPE and tmp.BOOKSET_ID = BOK.BOOKSET_ID

		SELECT 
			* 
		FROM(
		      SELECT 
		          A.*
		      FROM (
        SELECT tmp.*,
        @rownum := @rownum + 1 rownum, /* 虚拟列行标 */
        IF(
        (
        @BOOKSET_ID = tmp.BOOKSET_ID
        and @BOK_DETAIL_ID = tmp.BOK_DETAIL_ID
        ), @rank := @rank + 1, @rank := 1) AS rn, /* 分组虚拟列行标 */
        @BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
        , @BOK_DETAIL_ID := tmp.BOK_DETAIL_ID /* 分组条件1 */
        FROM (
        /* 数据源 */
        SELECT * FROM BOK_BOOKDETAIL_CURRENT_EXT ORDER BY BOOK_SUMMARY_ORDER DESC,ACCR_DATE DESC
        ) tmp,
        /* 定义临时变量池 */
        (SELECT @rownum := 0,
        @BOOKSET_ID := null,
        @BOK_DETAIL_ID := null,
        @rank := 0) a
        ) A
		      WHERE 1=1
		       AND A.ACCR_DATE <= #{searchDate,jdbcType=DATE} 
		      AND A.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
		       AND A.BOK_DETAIL_ID = #{bokdetailId,jdbcType=VARCHAR} 
		      AND A.BOOK_DATE <= #{bookDate,jdbcType=DATE}
		) WHERE RN = 1

select * from BOK_ACCT_LAYERING_INFO 
where bok_detail_id = #{bokDetailId,jdbcType=VARCHAR}
and LIMIT = 1

select * from BOK_ACCT_LAYERING_INFO 
where busi_id = #{busiId}
and branch = #{branch}
and LIMIT = 1
